def build():
    import ai_diagram
    rows = [r + (None,) for r in ROWS] + [r + (S, "CSE 325") for r in ai_diagram.ROWS]
    out = []
    for i, r in enumerate(rows, 1):
        year, qno, marks, page, q, f, les, key, typ, inn, course = r
        out.append(dict(id=i, year=year, course=course or COURSE[year], qno=qno, marks=marks, page=page,
                        question=q, file=f, lesson=les, key=key, type=typ, in_notes=inn,
                        teacher="Anindya" if f.startswith("A") or f == "OA" else "IJ"))
    # same-type lists (topic rows only)
    for r in out:
        if r["file"] in ("OA", "OI"):
            continue
        others = [o for o in out if o is not r and o["key"] == r["key"] and o["file"] not in ("OA", "OI")]
        r["same_type"] = "; ".join(f"{o['year']} {o['qno']}" + (" (CSE 325)" if o["course"] == "CSE 325" else "") for o in others[:6]) or "—"
    return out


if __name__ == "__main__":
    data = build()
    here = os.path.dirname(os.path.abspath(__file__))
    with open(os.path.join(here, "questions.json"), "w", encoding="utf-8") as fh:
        json.dump(data, fh, ensure_ascii=False, indent=1)
    from collections import Counter
    print(len(data), "rows")
    print(Counter((d["year"]) for d in data))
    print(Counter(d["file"] for d in data))
